    why = "Change one thing (the independent variable) and keep the rest the same." },
  { lv = 1, q = "In the rocket test, what is Fizzwick measuring?", a = "How high the rocket flies", d = { "Which fuel smells best", "The rocket's color", "The day of the week" },
    why = "The thing you measure is the dependent variable." },
  { lv = 1, q = "A testable prediction about what will happen is called a...", a = "Hypothesis", d = { "Conclusion", "Variable", "Result" }, t = { "hypothesis", "a hypothesis" },
    why = "A hypothesis is an idea you can test, like 'If..., then...'." },
  { lv = 1, q = "Which is the best hypothesis?", a = "If plants get more light, they will grow taller", d = { "Plants are nice", "I like plants a lot", "Plants might do something" },
    why = "A good hypothesis can be tested and says what you expect to happen." },
  { lv = 1, q = "Before mixing liquids in a lab test, you should...", a = "Wear goggles and follow the steps", d = { "Taste each liquid first", "Mix everything quickly", "Skip the instructions" },
    why = "Safety first: protect your eyes and never taste lab chemicals." },
  { lv = 2, q = "The variable you change on purpose is called the...", a = "Independent variable", d = { "Dependent variable", "Controlled variable", "Conclusion" }, t = { "independent", "independent variable" },
    why = "You choose it independently. Everything else stays controlled." },
  { lv = 2, q = "The variable you measure to see what happened is called the...", a = "Dependent variable", d = { "Independent variable", "Controlled variable", "Hypothesis" }, t = { "dependent", "dependent variable" },
